import vertexai
from vertexai.preview.generative_models import GenerativeModel, HarmCategory, HarmProbability

def check_platform_output_safety(text_content: str):
    """
    Checks the platform model output for unsafe content using Google's Vertex AI safety attributes.

    Args:
        text_content: The text content from the platform model output to be checked.

    Returns:
        A dictionary containing the safety attributes if available, otherwise None.
    """
    vertexai.init(project="your-gcp-project-id", location="your-gcp-region")

    model = GenerativeModel("gemini-pro")

    response = model.generate_content(
        text_content,
        safety_settings={
            HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT: HarmProbability.HARM_BLOCK_THRESHOLD_UNSPECIFIED,
            HarmCategory.HARM_CATEGORY_HARASSMENT: HarmProbability.HARM_BLOCK_THRESHOLD_UNSPECIFIED,
            HarmCategory.HARM_CATEGORY_HATE_SPEECH: HarmProbability.HARM_BLOCK_THRESHOLD_UNSPECIFIED,
            HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT: HarmProbability.HARM_BLOCK_THRESHOLD_UNSPECIFIED,
        }
    )

    if response and hasattr(response, 'candidates') and response.candidates:
        safety_attributes = {}
        for candidate in response.candidates:
            if hasattr(candidate, 'safety_ratings'):
                for rating in candidate.safety_ratings:
                    safety_attributes[rating.category.name] = rating.probability.name
                return safety_attributes
    return None

from typing import Any, Dict, List, Optional, Union

class ModelRequest:
    def __init__(self, instances: List[Dict[str, Any]], parameters: Optional[Dict[str, Any]] = None):
        self.instances = instances
        self.parameters = parameters if parameters is not None else {}

class ModelResponse:
    def __init__(self, predictions: List[Any], deployed_model_id: Optional[str] = None):
        self.predictions = predictions
        self.deployed_model_id = deployed_model_id

def normalize_text_generation_output(response_data: Dict[str, Any]) -> List[str]:
    normalized_outputs = []
    if "predictions" in response_data:
        for prediction in response_data["predictions"]:
            if isinstance(prediction, dict) and "displayText" in prediction:
                normalized_outputs.append(prediction["displayText"])
            elif isinstance(prediction, str):
                normalized_outputs.append(prediction)
    return normalized_outputs

from google.cloud import aiplatform

def resolve_model_resource(project_id: str, location: str, model_id: str) -> str:
    """Resolves a Vertex AI model resource name."""
    return aiplatform.models.Model.to_resource_name(project_id, location, model_id)

def resolve_endpoint_resource(project_id: str, location: str, endpoint_id: str) -> str:
    """Resolves a Vertex AI endpoint resource name."""
    return aiplatform.Endpoint.to_resource_name(project_id, location, endpoint_id)
